/// <summary>
/// This is a service class
/// CB355_DutyRoll
/// </summary>
class METDutyRollMonthlyService extends SysOperationServiceBase
{
    List                        itemList;
    List                        siteList;
    boolean                     adHoc;
    boolean                     runForExcise;
    RecordInsertList            recordInsertList;    
    boolean                     immediateChange;
    int                         totalTasks;
    TransDate                   startDate;
    METDutyRollMonthlyTmp       dutyRollMonthlyTmp;
    private TransDate           effectiveDate;
    private boolean             cpi;

}

Method.Source:
    /// <summary>
    /// Process Duty Roll Monthly in multi threading mode.
    /// <summary>
    public void processDutyRollMonthly()
    {
        #OCCRetryCount

        METDutyRollMonthlyContract      metDataContract;
        SysOperationServiceController   controller;
        Int                             bundlesize;
        BatchHeader                     batchHeader;
        int                             counter = 0;
        Int                             numOfOrders = this.getTotalRecords();
        container                       conItems;

        boolean                         businessEventTaskCreated = false;

        SysOperationServiceController   businessEventController;

        if (totalTasks  <= 0)// || adHoc) //commented as adhoc will be removed
        {
            totalTasks  = 1;
        }

        bundleSize      = real2int(roundUp((numOfOrders / totalTasks), 1.0));

        batchHeader     = this.getCurrentBatchHeader();

        if (batchHeader == null)
        {
            batchHeader = batchHeader::construct();
        }

        try
        {
           while select dutyRollMonthlyTmp
            {
                counter += 1;

                if (counter == 1)
                {
                    conItems = conNull();
                }

                conItems += [dutyRollMonthlyTmp];
    
                if (counter == bundlesize)
                {                    
                    controller      = new SysOperationServiceController(
                                                    classStr(METDutyRollMonthlyProcessingJob),
                                                    methodStr(METDutyRollMonthlyProcessingJob, process));

                    controller.parmDialogCaption(strFmt("@MET:DutyRollMonthlySubTask", counter));

                    metDataContract = controller.getDataContractObject() as METDutyRollMonthlyContract;
                    metDataContract.parmStartDate(startDate);
                    metDataContract.parmRunForExcise(runForExcise);
                    metDataContract.parmConItems(conItems);
                    metDataContract.parmCPI(cpi);
                    metDataContract.parmEffectiveDate(effectiveDate);

                    if (!businessEventTaskCreated)
                    {
                        metDataContract.parmBusinessEventTask(true);
                        businessEventTaskCreated = true;
                        businessEventController = controller;
                        batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);
                    }
                    else
                    {
                        batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);
                        batchHeader.addDependency(businessEventController, controller);
                    }
                    
                    counter = 0;              
                }
            }
            if (counter > 0)
            {
                controller      = new SysOperationServiceController(
                                                    classStr(METDutyRollMonthlyProcessingJob),
                                                    methodStr(METDutyRollMonthlyProcessingJob, process));

                controller.parmDialogCaption(strFmt("@MET:DutyRollMonthlySubTask", counter));

                metDataContract = controller.getDataContractObject() as METDutyRollMonthlyContract;
                metDataContract.parmStartDate(startDate);
                metDataContract.parmRunForExcise(runForExcise);
                metDataContract.parmConItems(conItems);
                metDataContract.parmCPI(cpi);
                metDataContract.parmEffectiveDate(effectiveDate);

                if (!businessEventTaskCreated)
                {
                    metDataContract.parmBusinessEventTask(true);
                    businessEventTaskCreated = true;
                    businessEventController = controller;
                    batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);
                }
                else
                {
                    batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);
                    batchHeader.addDependency(businessEventController, controller);
                }
            }
            batchHeader.save();
        }
        catch(Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }

    /// <summary>
    /// main process method
    /// </summary>
    /// <param name = "_dataContract">Contract</param>
    public void processOperation(METDutyRollMonthlyContract _dataContract)
    {        
        try
        {
            ttsbegin;
            itemList        = _dataContract.parmItemList();
            siteList        = _dataContract.parmSiteList();
            adHoc           = _dataContract.parmAdHoc();
            runForExcise    = _dataContract.parmRunForExcise();
            immediateChange = _dataContract.parmImmediateChange();
            totalTasks      = _dataContract.parmParallelTasksNumber();
            effectiveDate   = _dataContract.parmEffectiveDate();
            cpi             = _dataContract.parmCpi();

            recordInsertList = new RecordInsertList(tableNum(METDutyRollMonthlyTmp), true, true, true, true, true, dutyRollMonthlyTmp);

            //this.setStartDate(); //Set start date based on adHoc and immediateChange
            startDate = _dataContract.parmEffectiveDate(); //Set start date based on the effective date entered in the UI
            this.processSites(); //Prepare data for Duty Roll Monthly.
            ttscommit;

            this.processDutyRollMonthly(); //Process Duty Roll Monthly in multi threading mode.
        }
        catch
        {
            error ("@WAX:UpdateCancelled");
        }
        
        //Call Generate Ad Valorum Claim Batch
        if (adHoc)
        {
            this.processGenerateAdValorumClaimBatch(siteList, itemList);
        }
    }

    /// <summary>
    /// Call Generate Ad Valorum Claim Batch
    /// </summary>
    /// <param name = "_siteList">SiteList</param>
    /// <param name = "_itemList">ItemList</param>
    public void processGenerateAdValorumClaimBatch(List _siteList, List _itemList)
    {
        try
        {
            ttsbegin;
            BatchHeader     batchHeader;
                
            batchHeader = this.getCurrentBatchHeader(); 

            SysOperationServiceController controller = new SysOperationServiceController(classStr(METDutyAdValorumClaimGenerateService), methodStr(METDutyAdValorumClaimGenerateService, processOperation), SysOperationExecutionMode::ScheduledBatch);
            controller.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);
            controller.parmShowDialog(false);
            controller.parmLoadFromSysLastValue(false);
            controller.parmDialogCaption("@MET:GenerateAdValorumClaim");
 
            // Set contract parameters
            METDutyAdValorumClaimGenerateContract contract = new METDutyAdValorumClaimGenerateContract();
            contract = controller.getDataContractObject();
            contract.parmDutyValuesBySite(true);
            contract.parmGenerateClaims(false);
            contract.parmFilterItemSite(true);
            contract.parmSiteList(_siteList);
            contract.parmItemList(_itemList);

            //add the batch tasks to the batch header
            batchHeader.addTask(controller);

            //save the batch
            batchHeader.save();
            ttscommit;
        }
        catch
        {
            error ('@MET:GenerateAdValorumFailureMsg');
        }
    }

    /// <summary>
    /// process selected/all sited
    /// </summary>
    private void processSites()
    {
        InventSite              inventSite;
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource;
        ListEnumerator          iter = siteList.getEnumerator();
        
        queryBuildDataSource =   query.addDataSource(tableNum(InventSite));
        queryBuildDataSource.addRange(fieldNum(InventSite, METBondedWarehouse)).value(enum2str(NoYes::Yes));

        while (iter.moveNext())
        {
            queryBuildDataSource.addRange(fieldNum(InventSite, SiteId)).value(iter.current());
        }

        QueryRun queryRun = new QueryRun(query);
        while (queryRun.next())
        {
            inventSite = queryRun.get(tableNum(InventSite));
            this.processSite(inventSite.SiteId);
        }
    }

    /// <summary>
    /// process one sited
    /// </summary>
    /// <param name = "_siteId">InventSiteId</param>
    private void processSite(InventSiteId   _siteId)
    {
        try
        {
            List newItemList = new List(Types::String);
            
            boolean shouldProcessItems;

            if (!itemList.empty())
            {
                ListEnumerator iter = itemList.getEnumerator();

                while (iter.moveNext())
                {
                    ItemId itemId  = iter.current();
                    METDutyRollValuesLine dutyRollValuesLine = METDutyRollValuesLine::find(_siteId, itemId);

                    if (dutyRollValuesLine.RecId)
                    {
                        dutyRollMonthlyTmp.clear();
                        dutyRollMonthlyTmp.SiteId = _siteId;
                        dutyRollMonthlyTmp.ItemId = itemId;
                        
                        recordInsertList.add(dutyRollMonthlyTmp);
                    }
                    else
                    {
                        newItemList.addEnd(itemId);
                    }
                }

                if (!newItemList.empty())
                {
                    this.processItems(_siteId, newItemList);
                }

                recordInsertList.insertDatabase();
            }
            else
            {                
                const   str             tariffCodeC = "@MET:TariffCodeC";
                const   str             tariffCodeE = "@MET:TariffCodeE";
                Query                   query = new Query(queryStr(METInventTableTariffItemCode));
                InventTable             inventTable;

                if(!cpi)
                {
                    //Excise/Customs filter
                    query.dataSourceTable(tableNum(METTariffItemCodeBase)).addRange(fieldNum(METTariffItemCodeBase, CustomsExcise)).value(queryValue((!runForExcise) ? tariffCodeC : tariffCodeE));
                }
                QueryRun                queryRunItem = new  QueryRun(query);
              
                while (queryRunItem.next())
                {
                    inventTable = queryRunItem.get(tableNum(InventTable));  
                    METDutyRollValuesLine dutyRollValuesLine = METDutyRollValuesLine::find(_siteId, inventTable.ItemId);

                    if (dutyRollValuesLine.RecId)
                    {
                        dutyRollMonthlyTmp.clear();
                        dutyRollMonthlyTmp.SiteId = _siteId;
                        dutyRollMonthlyTmp.ItemId = inventTable.ItemId;
                        
                        recordInsertList.add(dutyRollMonthlyTmp);
                    }
                    else
                    {
                        newItemList.addEnd(inventTable.ItemId);
                    }
                }
                recordInsertList.insertDatabase();

                if (!newItemList.empty())
                {
                    this.processItems(_siteId, newItemList);
                }
            }
        }
        catch (Exception::Error)
        {
            error("@SYS93289");
            exceptionTextFallThrough();
        }
    }

    /// <summary>
    /// process selected/all items
    /// </summary>
    /// <param name = "_siteId">InventSiteId</param>
    /// <param name = "_itemList">ItemList</param>
    private void processItems(InventSiteId  _siteId, List _newItemList) 
    {
        const   str             tariffCodeC = "@MET:TariffCodeC";
        const   str             tariffCodeE = "@MET:TariffCodeE";
        InventTable             inventTable;
        QueryRun                queryRunItem;
        Query                   query = new Query(queryStr(METInventTableTariffItemCode));                
        ListEnumerator          iter = _newItemList.getEnumerator();
        
        if(!cpi)
        {   //Excise/Customs filter
            query.dataSourceTable(tableNum(METTariffItemCodeBase)).addRange(fieldNum(METTariffItemCodeBase, CustomsExcise)).value(queryValue((!runForExcise) ? tariffCodeC : tariffCodeE));
        }
        while (iter.moveNext())
        {            
            query.dataSourceTable(tableNum(InventTable)).addRange(fieldNum(InventTable, ItemId)).value(iter.current());
        }

        queryRunItem = new QueryRun(query);
        while (queryRunItem.next())
        {            
            inventTable = queryRunItem.get(tableNum(InventTable));

            dutyRollMonthlyTmp.clear();
            dutyRollMonthlyTmp.SiteId = _siteId;
            dutyRollMonthlyTmp.ItemId = inventTable.ItemId;
            //dutyRollMonthlyTmp.RefRecId = _refRecId;
            recordInsertList.add(dutyRollMonthlyTmp);      
        }
    }

