    /// <summary>
    /// calculate date for the first monday of the next month
    /// </summary>
    /// <returns>TransDate</returns>
    private TransDate getFstMonday()
    {
        TransDate   transDate;
        int         day;
        int         daysToAdd;

        transDate   = dateMthFwd(DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone()), 1);
        //1st day if the next month
        transDate   = mkDate(1, mthOfYr(transDate), Year(transDate));
        //day of the week on the 1st day on the next month
        day         = dayOfWk(transDate);
        //count days to the next Monday
        daysToAdd   = 8 - day;
        //1st Monday of the next month
        transDate   = transDate + daysToAdd;

        return transDate;
    }

    /// <summary>
    /// calculate date for the next monday of the current date
    /// </summary>
    /// <returns>TransDate</returns>
    private TransDate getNextMonday()
    {
        TransDate   transDate;
        int         day;
        int         daysToAdd;
        const int   valEight = 8;

        transDate   = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());

        day         = dayOfWk(transDate);
        daysToAdd   = valEight - day;
        
        transDate   = transDate + daysToAdd;

        return transDate;
    }

/// <summary>
/// Get the total number records to be processed
/// </summary>
/// <returns>Count</returns>
public int getTotalRecords()
{
    select count(RefRecId) from dutyRollMonthlyTmp;
    
    return dutyRollMonthlyTmp.RefRecId;
}
